	allegiance = "Jabaespines Rajacieno",
	aliases = { "Razorflank", "la Bruja del Horado", "la Bruja" },
	sections = {
		{
			title = "Resumen",
			text = [=[Charlga Razorflank es la bruja del {link:razorfen-kraul}Horado Rajacieno{/link}, una anciana {link:quilboar}jabaespín{/link} y una poderosa maestra de la magia de la tierra. Gobierna la gran madriguera desde una choza en lo alto de sus espinos. Bajo su mando, los jabaespines del Horado se han envalentonado. Atacan a tribus rivales y a las aldeas de la {link:horde}Horda{/link}, toman prisioneros y se preparan para la guerra. Considera suyas las tierras que rodean el Horado, y trata a todo forastero como a un ladrón.]=],
		},
		{
			title = "Importancia",
			text = [=[Charlga es el poder en ascenso del sur de {link:the-barrens}Los Baldíos{/link}. Los druidas elfos de la noche temen que la corrupción de los espinos se extienda desde su dominio. Los {link:tauren}tauren{/link} de {link:thunder-bluff}Cima del Trueno{/link} culpan a su pueblo de haberlos expulsado de su tierra sagrada. Y la {link:scourge}Plaga{/link} la ha buscado como aliada en {link:kalimdor}Kalimdor{/link}. Si ha aceptado su oferta, nadie fuera del {link:razorfen-kraul}Horado{/link} sabe decirlo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Se apoderó del {link:razorfen-kraul}Horado{/link} y reunió a los jabaespines bajo su mando.
• Sus guerreros capturaron al druida {link:heralath-fallowbrook}Heralath{/link} y al {link:dwarves}enano{/link} Henrig Lonebrow.
• Recibió cartas del enviado de la {link:scourge}Plaga{/link}, {link:ambassador-malcin}Malcin{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La advertencia",
			hint = "Lleve a Thalanaar la advertencia de un enano muerto.",
			text = [=[Henrig Lonebrow escapó del {link:razorfen-kraul}Horado{/link} con una advertencia para {link:falfindel-waywarder}Falfindel Waywarder{/link}, en {link:thalanaar}Thalanaar{/link}: la bruja estaba agitando a sus esbirros, y su poder crecía día a día. El {link:dwarves}enano{/link} murió antes de poder entregarla. Su diario hizo el trabajo por él. Falfindel envió a otros a acabar con la vida de la bruja, con la esperanza de que, sin ella, su pueblo pudiera averiguar qué había corrompido el lugar de reposo de Agamaggan.]=],
		},
		{
			title = "Un destino vengativo",
			hint = "Responda al anciano tauren que no puede perdonar.",
			text = [=[{red:auld-stonespire}Auld Stonespire{/red}, de {link:thunder-bluff}Cima del Trueno{/link}, honra a {link:cairne-bloodhoof}Cairne Bloodhoof{/link} por haber unido a los {link:tauren}tauren{/link}, pero no puede perdonar a quienes expulsaron a su pueblo del sur de {link:the-barrens}Los Baldíos{/link}. Pidió el corazón de la bruja. Cuando se lo llevaron, dijo que los jabaespines del {link:razorfen-kraul}Horado{/link} conocían ahora el dolor de su pueblo.]=],
		},
		{
			title = "La carta del enviado",
			hint = "Busque lo que la bruja guarda cerca.",
			text = [=[En la bruja se encontró un pequeño pergamino. Estaba firmado por el embajador {link:ambassador-malcin}Malcin{/link}, que le prometía {link:the-barrens}Los Baldíos{/link} y más a cambio de libertad para actuar allí. {link:varimathras}Varimathras{/link} reconoció el sello al instante. Juzgó que la bruja todavía no había cedido, quizá porque intuía que, con semejantes aliados, Los Baldíos nunca serían de verdad suyos.]=],
		},
	},
	mentions = {
		{ text = "Diario de Soliceja" },
		{ text = "Una alianza impía" },
	},
	bonds = {
		{ id = "overlord-ramtusk", name = "Señor supremo Ramtusk", note = "manda a sus guerreros" },
		{ id = "heralath-fallowbrook", name = "Heralath Fallowbrook", note = "su prisionero" },
		{ id = "varimathras", name = "Varimathras", note = "leyó la carta que ella guardaba" },
	},
})

