	},
	mentions = {
		{ text = "Malla endurecida al fuego" },
		{ text = "Armadura brutal" },
	},
	bonds = {
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "la bruja a la que sirve" },
	},
})

Translate("esES", "agathelos-the-raging", {
	title = "Agathelos el Furioso",
	subtitle = "El jabalí encerrado",
	found = [=[Un túnel sellado más allá de las cuevas de los murciélagos del Horado Rajacieno]=],
	hint = [=[Busque al gran jabalí que los jabaespines guardan tras su barrera.]=],
	allegiance = "Ninguna",
	aliases = { "Agathelos" },
	sections = {
		{
			title = "Resumen",
			text = [=[Agathelos el Furioso es un colosal jabalí acorazado al que se guarda en un túnel del {link:razorfen-kraul}Horado Rajacieno{/link}. Unos cuidadores jabaespines lo retienen tras una barrera de magia. Para un pueblo que llama dios a un gran jabalí, semejante bestia no es un animal corriente: se dice que ven en un jabalí poderoso un regalo de Agamaggan. También se dice que lo han alimentado con el guano de los murciélagos del Horado, que lo vuelve loco y aún más fuerte, y que los {link:death-s-head}Galponmuerte{/link} pretenden soltarlo contra sus enemigos.]=],
		},
		{
			title = "Importancia",
			text = [=[Agathelos es un arma que se está preparando, un eco vivo del dios al que venera {link:razorfen-kraul}el Horado{/link}.]=],
		},
		{ title = "Hazañas", text = "• Se enfurece en su corral, y crece con su furia." },
	},
	bonds = {
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "su guardiana" },
	},
})

Translate("esES", "blind-hunter", {
