	allegiance = "Ninguna",
	sections = {
		{
			title = "Resumen",
			text = [=[El Cazador Ciego es un gran murciélago pálido que ronda las cuevas más profundas del {link:razorfen-kraul}Horado Rajacieno{/link}. Rara vez se le ve, incluso los jabaespines. Vive donde no llega la luz, y parece no necesitar ojos. Los murciélagos del Horado menores anidan más cerca de la boca de los túneles. Sus excrementos son tan raros que la {link:royal-apothecary-society}Real Sociedad de Boticarios{/link} de {link:undercity}Entrañas{/link} ha mandado a buscarlos.]=],
		},
		{
			title = "Importancia",
