		},
	},
	mentions = {
		{ text = "Tubérculos de hoja azul" },
	},
	bonds = {
		{ id = "heralath-fallowbrook", name = "Heralath Fallowbrook", note = "un compañero de cautiverio" },
	},
})

Translate("esES", "heralath-fallowbrook", {
	title = "Heralath Fallowbrook",
	subtitle = "Druida de Darnassus",
	found = [=[Una choza de prisioneros en las profundidades del Horado Rajacieno]=],
	hint = [=[Busque al elfo de la noche herido que está cautivo en el Horado.]=],
	allegiance = "Elfos de la noche · Darnassus",
	aliases = { "Heralath" },
	sections = {
		{
			title = "Resumen",
			text = [=[Heralath Fallowbrook es un druida {link:night-elves}elfo de la noche{/link} que vino al sur de {link:the-barrens}Los Baldíos{/link} para conocer la verdad sobre el dios jabalí caído. Creía que el gran cráneo de las llanuras marcaba el lugar donde cayó Agamaggan, y su pueblo deseaba saber por qué el lugar de reposo de un ser tan puro se había corrompido. Los jabaespines lo capturaron, lo azotaron y lo arrojaron a una choza del {link:razorfen-kraul}Horado{/link}. Allí compartió celda con el {link:dwarves}enano{/link} {red:henrig-lonebrow}Henrig Lonebrow{/red}, y le confió una advertencia para {link:falfindel-waywarder}Falfindel Waywarder{/link}.]=],
		},
	},
	chapters = {
		{
